const products=[{id:1,name:'The Celebration Dress',category:'Dresses',price:185,image:'https://images.unsplash.com/photo-1539008835657-9e8e9680c956?w=800&q=85',color:'Golden hour',description:'A statement silhouette for evenings worth dressing up for. An illustrative occasionwear direction for the Atunbi collection.',fit:'Sample size options only. Final garment measurements and fabric details are still to be confirmed.'},{id:2,name:'The City Layer',category:'Layers',price:165,image:'https://images.unsplash.com/photo-1539109136881-3be0616acf4b?w=1200&q=85',color:'Soft blue',description:'A considered layer that brings structure and personality to an everyday look. Shown as a styling reference, not an Atunbi product.',fit:'Sample size options only. Ask for approved garment measurements before choosing a production size.'},{id:3,name:'The Signature Edit',category:'Separates',price:145,image:'https://images.unsplash.com/photo-1531123897727-8f129e1688ce?w=1200&q=85',color:'Modern neutral',description:'An expressive wardrobe direction for your next chapter. This editorial photograph is a visual reference for the collection concept.',fit:'This is a concept piece. Final sizes, materials, measurements and availability are not yet established.'}];
let bag=[],currentProduct=null,selectedSize='',voice=false,spokenText='',toastTimer;const $=id=>document.getElementById(id);const money=n=>'$'+n.toFixed(0);function renderProducts(filter='All'){$('products').replaceChildren();const list=products.filter(p=>filter==='All'||p.category===filter);$('results').textContent=list.length+' concept piece'+(list.length===1?'':'s');list.forEach(p=>{const card=document.createElement('article');card.className='product-card';card.innerHTML=`<div class="product-photo"><button aria-label="View ${p.name}" onclick="openProduct(${p.id})"><img src="${p.image}" alt="Stock editorial reference for ${p.name}" loading="lazy"></button><span class="tag">CONCEPT ${String(p.id).padStart(2,'0')}</span><span class="quick-view">EXPLORE THE PIECE ↗</span></div><div class="product-info"><h3>${p.name}</h3><span>${money(p.price)}</span></div><p>${p.color} · Sample price</p><span class="swatch" style="background:${p.id===1?'#b48c44':p.id===2?'#9fb6bb':'#766b52'}"></span>`;$('products').append(card)})}document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderProducts(b.dataset.filter)}));
function openProduct(id){currentProduct=products.find(p=>p.id===id);selectedSize='';const p=currentProduct;$('productDetail').innerHTML=`<div class="detail-grid"><img src="${p.image}" alt="Editorial reference for ${p.name}"><div class="detail-copy"><p class="eyebrow">ATUNBI CONCEPT COLLECTION</p><h2>${p.name}</h2><p class="detail-price">${money(p.price)} <small>sample price</small></p><p>${p.description}</p><p>Choose a sample size</p><div class="sizes">${['XS','S','M','L','XL'].map(s=>`<button onclick="selectSize(this,'${s}')" aria-pressed="false">${s}</button>`).join('')}</div><button class="primary" id="addBag" disabled onclick="addToBag()">Select a size <span>+</span></button><p class="fit-note">${p.fit}</p><button class="text" onclick="closeProduct();openStylist();ask('Help with sizing')">Ask your stylist about fit ↗</button></div></div>`;$('productDialog').showModal()}function selectSize(el,s){selectedSize=s;document.querySelectorAll('.sizes button').forEach(b=>{b.classList.remove('selected');b.setAttribute('aria-pressed','false')});el.classList.add('selected');el.setAttribute('aria-pressed','true');$('addBag').disabled=false;$('addBag').innerHTML='Add to sample bag <span>+</span>'}function closeProduct(){$('productDialog').close()}function addToBag(){if(!currentProduct||!selectedSize)return;bag.push({...currentProduct,size:selectedSize,key:Date.now()+Math.random()});$('bagCount').textContent=bag.length;closeProduct();notify('Added to your sample bag')}function notify(t){$('toast').textContent=t;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2500)}function renderBag(){$('bagItems').innerHTML=bag.length?bag.map(p=>`<div class="bag-item"><img src="${p.image}" alt="${p.name}"><div><h3>${p.name}</h3><p>Size ${p.size} · ${money(p.price)} sample price</p><button onclick="removeItem(${p.key})">Remove</button></div></div>`).join(''):'<p class="empty-bag">Your next chapter starts here.<br>Explore a concept piece and add it to your sample bag.</p>';$('total').textContent=money(bag.reduce((a,p)=>a+p.price,0));$('bagCount').textContent=bag.length}function showBag(){renderBag();$('checkoutNote').textContent='No orders or payments are processed.';$('bagDialog').showModal()}function removeItem(key){bag=bag.filter(p=>p.key!==key);renderBag()}
function appendMessage(text,user=false,recommendation){const m=document.createElement('div');m.className='message'+(user?' user':'');m.textContent=text;if(recommendation){const b=document.createElement('button');b.textContent='Explore '+recommendation.name+' · '+money(recommendation.price)+' sample';b.onclick=()=>{closeStylist();openProduct(recommendation.id)};m.append(b)}$('chat').append(m);$('chat').scrollTop=$('chat').scrollHeight;if(!user){spokenText=text;if(voice)speak(text)}}function openStylist(){if(!$('stylistDialog').open)$('stylistDialog').showModal();if(!$('chat').children.length)appendMessage('Welcome to Atunbi Coterie. I’m Tuni, your virtual stylist concept. Are you dressing for a celebration or exploring a fresh everyday look?')}function stopSpeech(){if('speechSynthesis'in window)window.speechSynthesis.cancel();$('avatarStage').classList.remove('speaking')}function closeStylist(){stopSpeech();$('stylistDialog').close()}function speak(text){if(!('speechSynthesis'in window))return;stopSpeech();const u=new SpeechSynthesisUtterance(text);u.rate=.93;u.onstart=()=>$('avatarStage').classList.add('speaking');u.onend=u.onerror=()=>$('avatarStage').classList.remove('speaking');window.speechSynthesis.speak(u)}function toggleVoice(){if(!('speechSynthesis'in window)){notify('Voice preview is unavailable in this browser. Text styling still works.');return}voice=!voice;$('voiceToggle').textContent=voice?'◖ Mute voice preview':'◖ Enable voice preview';if(voice)speak(spokenText||'Welcome to Atunbi Coterie.');else stopSpeech()}function ask(input){const q=input.trim();if(!q)return;appendMessage(q,true);const t=q.toLowerCase();if(/size|fit|measure/.test(t))appendMessage('Fit should feel as good as it looks. This concept has no verified size chart yet, so I can’t recommend a size. In the live boutique, I would compare your preferences with each garment’s approved measurements.');else if(/birthday|dinner|celebrat|party|dress|occasion/.test(t))appendMessage('For a birthday dinner, I’d start with a statement silhouette and let the outfit lead. Explore the Celebration Dress concept for this direction. The photo and price are illustrative.',false,products[0]);else if(/everyday|work|casual|layer|blue/.test(t))appendMessage('For everyday style, a thoughtful layer can give a familiar outfit a fresh point of view. Explore the City Layer concept as inspiration.',false,products[1]);else if(/budget|price|cost|under|\$/.test(t))appendMessage('The sample edit ranges from $145 to $185. The Signature Edit is the lowest sample price. These figures are placeholders, not live prices.',false,products[2]);else if(/ship|return|deliver|stock|available/.test(t))appendMessage('Shipping, returns and inventory are not connected in this prototype. The live stylist will use approved store policies and current stock rather than guessing.');else appendMessage('This preview uses scripted styling responses. Try “birthday dinner,” “everyday style,” “help with sizing,” or a budget question to explore the experience. A live AI conversation will be a later integration.')} $('chatForm').addEventListener('submit',e=>{e.preventDefault();ask($('chatInput').value);$('chatInput').value=''});$('stylistDialog').addEventListener('close',stopSpeech);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopSpeech()});$('newsletter').addEventListener('submit',e=>{e.preventDefault();$('signupNote').textContent='Thank you for exploring the signup preview. Your email has not been submitted or saved.';$('email').value=''});renderProducts();
